#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void need(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}}
int main(){try{using Modules=std::vector<std::pair<StableId,StableId>>;Modules v{{task_personal_cancellation_module,"1"},{"task_personal_message_deliveries","1"},{"task_message_handoffs","3"},{"task_static_assets","1"},{"family_life","1"},{"known_personal_dialogues","1"}};need(task_personal_cancellation_selected_version(v).ok,"Q01 original delivery pair allows explicit cancellation");auto v4=v;v4[2].second="4";need(!task_personal_cancellation_selected_version(v4).ok,"handoff4 without original report source rejects");v4.push_back({"task_personal_message_reports","1"});need(task_personal_cancellation_selected_version(v4).ok,"complete handoff4 report pair also permits separate cancellation");need(task_personal_cancellation_selected_version({}).value==0,"old empty profile stays unselected");for(std::size_t i=1;i<v.size();++i){auto bad=v;bad.erase(bad.begin()+i);need(!task_personal_cancellation_selected_version(bad).ok,"missing Q01 dependency rejects");}for(const auto* old:{"1","2","5"}){auto bad=v;bad[2].second=old;need(!task_personal_cancellation_selected_version(bad).ok,"unsupported handoff cannot bypass original source");}for(const auto* excluded:{"task_message_notices","task_message_returns"}){auto bad=v;bad.push_back({excluded,"1"});need(!task_personal_cancellation_selected_version(bad).ok,"unclosed source combinations reject");}{auto bad=v;bad.push_back(v.front());need(!task_personal_cancellation_selected_version(bad).ok,"duplicate module rejected");}{auto bad=v;bad[0].second="2";need(!task_personal_cancellation_selected_version(bad).ok,"unknown cancellation version rejected");}
 TaskPersonalCancellationCatalog catalog;catalog.policies.push_back({"cancel","letter","sender","cancel"});TaskExtensionCatalog extension;TaskExtensionPolicy p;p.offer_id="other";extension.policies.push_back(p);need(validate_task_personal_cancellation_extension_pair(catalog,&extension).ok,"another Offer original extension unaffected");extension.policies.front().offer_id="letter";need(!validate_task_personal_cancellation_extension_pair(catalog,&extension).ok,"same Offer extension explicitly unsupported");
 auto common_catalog=std::make_shared<CommonCatalog>();CommonStore c{CommonState{},common_catalog};TaskPersonalCancellationState state;need(validate_task_personal_cancellation_layout(c,v,&state).ok,"empty selected new state valid");need(!validate_task_personal_cancellation_layout(c,v,nullptr).ok,"selected state cannot disappear");auto id=c.next_id(task_personal_cancelled_kind);need(id.ok&&c.append_fact({id.value,task_personal_cancelled_kind,task_personal_cancellation_module}).ok,"real Common cancellation head");need(!validate_task_personal_cancellation_layout(c,{},nullptr).ok,"unselected original facts rejected");need(!task_personal_cancellation_fact_payloads(c,&state).ok,"header without exact payload rejects");
 using V=BoundaryValue;auto request=boundary::obj({{"task_id",V{StableId{"task:7"}}}});need(decode_task_personal_cancel(task_personal_cancellation_command,request).ok,"request only supplies original Task ID");request.as<V::Dict>()->push_back({"refund",V{Integer{500}}});need(!decode_task_personal_cancel(task_personal_cancellation_command,request).ok,"caller cannot supply refund");std::cout<<checks<<" cancellation profile boundaries; full World separate\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
